#!/bin/bash
# Build the HTML documentation (coupled model) into docs/build.
# The API pages are hand-curated in docs/source/api.rst (autodoc), so there is no
# sphinx-apidoc step; Markdown pages are generated by docs/source/conf.py.
set -e
pip install -q sphinx sphinx-rtd-theme myst-parser
sphinx-build -b html docs/source docs/build
echo "Open docs/build/index.html"
